"""Additional mountain portraits and a separate lake collection; no invented trails."""
def extend_catalog(sources, mountains):
    checked='2026-10-01'
    def src(key,title,url,kind='地理与文化资料'):
        sources[key]=dict(id=key,title=title,url=url,kind=kind,checked=checked)
